package pe.nexo.store.order;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;
@Entity@Table(name="customer_orders",indexes=@Index(name="idx_order_email",columnList="email"))public class CustomerOrder{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,unique=true)private String orderNumber;@Column(nullable=false)private String customerName;@Column(nullable=false)private String email;@Column(nullable=false)private String phone;@Column(nullable=false)private String address;@Column(nullable=false)private String city;@Column(nullable=false)private String paymentMethod;private String couponCode;@Enumerated(EnumType.STRING)@Column(nullable=false)private OrderStatus status;@Column(nullable=false,precision=10,scale=2)private BigDecimal subtotal;@Column(nullable=false,precision=10,scale=2)private BigDecimal discount;@Column(nullable=false,precision=10,scale=2)private BigDecimal total;@Column(nullable=false)private LocalDateTime createdAt;@OneToMany(mappedBy="order",cascade=CascadeType.ALL,orphanRemoval=true)private List<OrderItem>items=new ArrayList<>();protected CustomerOrder(){}public CustomerOrder(String number,String name,String email,String phone,String address,String city,String payment,String coupon,BigDecimal subtotal,BigDecimal discount,BigDecimal total){this.orderNumber=number;this.customerName=name;this.email=email;this.phone=phone;this.address=address;this.city=city;this.paymentMethod=payment;this.couponCode=coupon;this.status=OrderStatus.CREATED;this.subtotal=subtotal;this.discount=discount;this.total=total;this.createdAt=LocalDateTime.now();}public void addItem(OrderItem item){items.add(item);item.assignTo(this);}public void changeStatus(OrderStatus status){this.status=Objects.requireNonNull(status);}public Long getId(){return id;}public String getOrderNumber(){return orderNumber;}public String getCustomerName(){return customerName;}public String getEmail(){return email;}public String getPhone(){return phone;}public String getAddress(){return address;}public OrderStatus getStatus(){return status;}public BigDecimal getTotal(){return total;}public LocalDateTime getCreatedAt(){return createdAt;}public List<OrderItem>getItems(){return List.copyOf(items);}}
